// Launchers of the compiled symmetric-contraction kernels, one explicit
// instantiation per (l_in, l_out, degree) in its own translation unit
// (generated by CMake from MOLNEX_SC_CONFIGS) so the unrolled kernels build
// in parallel.
#pragma once

#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>

#include <limits>

#include "contraction_compiled.cuh"

namespace molnex::equivariance::sc {

struct Args {
  at::Tensor x, w, index;       // (N, NS·U), (Z, NB·U), (N,) int32
  at::Tensor g, dgx, dgw;       // adjoints: (N, NO·U); second: (N, NS·U), (Z, NB·U)
  at::Tensor out_y;             // forward: (N, NO·U)
  at::Tensor out_x, out_w;      // adjoints: gx / dx (N, NS·U), the per-node weight partial (N, NB·U)
  at::Tensor out_g;             // second: dg (N, NO·U)
  at::ArrayRef<double> values;  // the NT coefficients
  int64_t channels, tile;
};

inline int config_id(int l_in, int l_out, int degree) { return l_in * 100 + l_out * 10 + degree; }

template <typename T, int LIN, int LOUT, int DEG>
Coefficients<T, Table<LIN, LOUT, DEG>::NT> pack_values(at::ArrayRef<double> values) {
  constexpr int NT = Table<LIN, LOUT, DEG>::NT;
  TORCH_CHECK(values.size() == size_t(NT), "the compiled table has ", NT, " terms, got ",
              values.size(), " coefficients");
  Coefficients<T, NT> c;
  for (int t = 0; t < NT; ++t) c.c[t] = T(values[t]);
  return c;
}

template <int LIN, int LOUT, int DEG>
void run_forward(const Args& a) {
  const int64_t n = a.x.size(0);
  if (n == 0) return;
  TORCH_CHECK(n <= std::numeric_limits<int>::max(), "too many nodes for one grid");
  AT_DISPATCH_FLOATING_TYPES(a.x.scalar_type(), "sc_forward", [&] {
    const auto coef = pack_values<scalar_t, LIN, LOUT, DEG>(a.values);
    forward_kernel<scalar_t, LIN, LOUT, DEG>
        <<<unsigned(n), unsigned(a.tile), 0, at::cuda::getCurrentCUDAStream()>>>(
            a.x.const_data_ptr<scalar_t>(), a.w.const_data_ptr<scalar_t>(),
            a.index.const_data_ptr<int32_t>(), a.out_y.mutable_data_ptr<scalar_t>(), a.w.size(0),
            a.channels, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

template <int LIN, int LOUT, int DEG>
void run_first(const Args& a) {
  const int64_t n = a.x.size(0);
  if (n == 0) return;
  TORCH_CHECK(n <= std::numeric_limits<int>::max(), "too many nodes for one grid");
  AT_DISPATCH_FLOATING_TYPES(a.x.scalar_type(), "sc_first", [&] {
    const auto coef = pack_values<scalar_t, LIN, LOUT, DEG>(a.values);
    first_kernel<scalar_t, LIN, LOUT, DEG>
        <<<unsigned(n), unsigned(a.tile), 0, at::cuda::getCurrentCUDAStream()>>>(
            a.x.const_data_ptr<scalar_t>(), a.w.const_data_ptr<scalar_t>(),
            a.index.const_data_ptr<int32_t>(), a.g.const_data_ptr<scalar_t>(),
            a.out_x.mutable_data_ptr<scalar_t>(), a.out_w.mutable_data_ptr<scalar_t>(), a.w.size(0),
            a.channels, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

template <int LIN, int LOUT, int DEG>
void run_second(const Args& a) {
  const int64_t n = a.x.size(0);
  if (n == 0) return;
  TORCH_CHECK(n <= std::numeric_limits<int>::max(), "too many nodes for one grid");
  AT_DISPATCH_FLOATING_TYPES(a.x.scalar_type(), "sc_second", [&] {
    const auto coef = pack_values<scalar_t, LIN, LOUT, DEG>(a.values);
    const auto stream = at::cuda::getCurrentCUDAStream();
    second_node_kernel<scalar_t, LIN, LOUT, DEG><<<unsigned(n), unsigned(a.tile), 0, stream>>>(
        a.x.const_data_ptr<scalar_t>(), a.w.const_data_ptr<scalar_t>(),
        a.index.const_data_ptr<int32_t>(), a.g.const_data_ptr<scalar_t>(),
        a.dgx.const_data_ptr<scalar_t>(), a.dgw.const_data_ptr<scalar_t>(),
        a.out_x.mutable_data_ptr<scalar_t>(), a.out_g.mutable_data_ptr<scalar_t>(), a.w.size(0),
        a.channels, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    second_weight_kernel<scalar_t, LIN, LOUT, DEG><<<unsigned(n), unsigned(a.tile), 0, stream>>>(
        a.x.const_data_ptr<scalar_t>(), a.index.const_data_ptr<int32_t>(),
        a.g.const_data_ptr<scalar_t>(), a.dgx.const_data_ptr<scalar_t>(),
        a.out_w.mutable_data_ptr<scalar_t>(), a.w.size(0), a.channels, coef);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
  });
}

#define MOLNEX_SC_DECLARE(A, B, C)                       \
  extern template void run_forward<A, B, C>(const Args&); \
  extern template void run_first<A, B, C>(const Args&);   \
  extern template void run_second<A, B, C>(const Args&);
MOLNEX_SC_CONFIGS(MOLNEX_SC_DECLARE)
#undef MOLNEX_SC_DECLARE

}  // namespace molnex::equivariance::sc
